using System.Net;
using System.Text.Json;
using Quill.Windows;
using Xunit;
namespace Quill.Windows.Tests;
public sealed class MockHttp(Func<HttpRequestMessage,CancellationToken,Task<HttpResponseMessage>> handle) : HttpMessageHandler {
 protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token) => handle(request,token);
 public static HttpResponseMessage Json(string json,int status = 200) => new((HttpStatusCode)status) { Content = new StringContent(json,System.Text.Encoding.UTF8,"application/json") };
}
public sealed class ProviderTests {
 private sealed class StalledStream : MemoryStream { public override async ValueTask<int> ReadAsync(Memory<byte> buffer,CancellationToken cancellationToken = default) { await Task.Delay(Timeout.Infinite,cancellationToken); return 0; } }
 private sealed class FailedStream : MemoryStream { public override ValueTask<int> ReadAsync(Memory<byte> buffer,CancellationToken cancellationToken = default) => throw new IOException("Untrusted transport details"); }
 [Fact] public async Task BodyTransportFailureMapsToNetworkWithoutLeakingDetails() { using var client = new ProviderClient(new MockHttp((_,_) => Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK) { Content = new StreamContent(new FailedStream()) }))); var error = await Assert.ThrowsAsync<ProviderException>(() => client.Transcribe(Audio,new(),"test-key",CancellationToken.None)); Assert.Equal("network",error.Code); Assert.DoesNotContain("Untrusted",error.Message); }
 [Theory][InlineData("{\"data\":[]}")][InlineData("{\"data\":[{\"id\":\"embedding-only\"}]}")]
 public async Task EmptyCompatibleCatalogIsRejected(string body) { using var client = new ProviderClient(new MockHttp((_,_) => Task.FromResult(MockHttp.Json(body)))); Assert.Equal("no_models",(await Assert.ThrowsAsync<ProviderException>(() => client.Models(Provider.Groq,"test-key","",true,CancellationToken.None))).Code); }
 [Fact] public async Task RepeatedGeminiPaginationTokenIsRejected() { int calls = 0; using var client = new ProviderClient(new MockHttp((_,_) => { calls++; return Task.FromResult(MockHttp.Json("{\"models\":[{\"name\":\"models/gemini-flash\",\"supportedGenerationMethods\":[\"generateContent\"]}],\"nextPageToken\":\"repeat\"}")); })); Assert.Equal("invalid_response",(await Assert.ThrowsAsync<ProviderException>(() => client.Models(Provider.Gemini,"test-key","",true,CancellationToken.None))).Code); Assert.Equal(2,calls); }
 [Fact] public async Task WholeRequestDeadlineIncludesStalledResponseBody() { using var client = new ProviderClient(new MockHttp((_,_) => Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK) { Content = new StreamContent(new StalledStream()) })),TimeSpan.FromMilliseconds(100)); var elapsed = System.Diagnostics.Stopwatch.StartNew(); Assert.Equal("timeout",(await Assert.ThrowsAsync<ProviderException>(() => client.Transcribe(Audio,new(),"test-key",CancellationToken.None))).Code); Assert.InRange(elapsed.ElapsedMilliseconds,50,3000); }
 [Fact] public async Task CallerCancellationDuringStalledBodyRemainsCancellation() { using var cancel = new CancellationTokenSource(100); using var client = new ProviderClient(new MockHttp((_,_) => Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK) { Content = new StreamContent(new StalledStream()) }))); await Assert.ThrowsAnyAsync<OperationCanceledException>(() => client.Transcribe(Audio,new(),"test-key",cancel.Token)); }
 [Theory][InlineData("{\"choices\":[]}")][InlineData("{\"choices\":[{}]}")][InlineData("{\"choices\":null}")][InlineData("{\"choices\":[{\"message\":{\"content\":42}}]}")]
 public async Task MalformedCleanupAlwaysPreservesRaw(string response) { using var client = new ProviderClient(new MockHttp((_,_) => Task.FromResult(MockHttp.Json(response)))); Assert.Equal("raw transcript",await client.Cleanup("raw transcript",new(),"test-key","unknown",CancellationToken.None)); }
 [Fact] public async Task CleanupDeadlineIsFourSecondsAndFallsBack() { var elapsed = System.Diagnostics.Stopwatch.StartNew(); using var client = new ProviderClient(new MockHttp(async (_,token) => { await Task.Delay(Timeout.Infinite,token); return MockHttp.Json("{}"); })); Assert.Equal("raw transcript",await client.Cleanup("raw transcript",new(),"test-key","unknown",CancellationToken.None)); Assert.InRange(elapsed.ElapsedMilliseconds,3500,6500); }
 private static byte[] Audio => AudioRecorder.Wav(new byte[32000]);
 [Theory][InlineData(Provider.Groq,"api.groq.com","/openai/v1/audio/transcriptions")][InlineData(Provider.OpenAI,"api.openai.com","/v1/audio/transcriptions")][InlineData(Provider.Custom,"speech.example.test","/proxy/v1/audio/transcriptions")]
 public async Task MultipartTranscriptionContractAndKeyIsolation(Provider provider,string host,string path) {
  var s = new QuillSettings { Provider = provider,SpeechModel = "chosen-model",CustomModel = "custom-model",CustomBaseUrl = "https://speech.example.test/proxy/v1",ContactNames = ["Private Imported Name"],ContactsEnabled = true };
  using var client = new ProviderClient(new MockHttp(async (request,token) => { Assert.Equal(host,request.RequestUri!.Host); Assert.Equal(path,request.RequestUri.AbsolutePath); Assert.Equal("Bearer",request.Headers.Authorization!.Scheme); Assert.Equal("test-key",request.Headers.Authorization.Parameter); var body = await request.Content!.ReadAsStringAsync(token); Assert.Contains("audio/wav",body); Assert.Contains(provider == Provider.Custom ? "custom-model" : "chosen-model",body); Assert.Contains("Hinglish",body); Assert.DoesNotContain("Private Imported Name",body); Assert.StartsWith("multipart/form-data",request.Content.Headers.ContentType!.MediaType); return MockHttp.Json("{\"text\":\"  hello world  \"}"); }));
  Assert.Equal("hello world",await client.Transcribe(Audio,s,"test-key",CancellationToken.None));
 }
 [Fact] public async Task AutoLanguageOmitsRomanizationAndLanguageParts() { using var client = new ProviderClient(new MockHttp(async (request,token) => { var body = await request.Content!.ReadAsStringAsync(token); Assert.DoesNotContain("Hinglish",body); Assert.DoesNotContain("name=language",body); Assert.DoesNotContain("name=prompt",body); return MockHttp.Json("{\"text\":\"नमस्ते\"}"); })); Assert.Equal("नमस्ते",await client.Transcribe(Audio,new QuillSettings { Language = "auto" },"test-key",CancellationToken.None)); }
 [Fact] public async Task OpenRouterUsesJsonInputAudioAndDedicatedEndpoint() { using var client = new ProviderClient(new MockHttp(async (request,token) => { Assert.Equal("https://openrouter.ai/api/v1/audio/transcriptions",request.RequestUri!.AbsoluteUri); using var body = JsonDocument.Parse(await request.Content!.ReadAsStringAsync(token)); Assert.Equal("wav",body.RootElement.GetProperty("input_audio").GetProperty("format").GetString()); Assert.Equal(Audio,Convert.FromBase64String(body.RootElement.GetProperty("input_audio").GetProperty("data").GetString()!)); Assert.False(body.RootElement.TryGetProperty("prompt",out _)); return MockHttp.Json("{\"text\":\"hello\"}"); })); await client.Transcribe(Audio,new QuillSettings { Provider = Provider.OpenRouter },"router-key",CancellationToken.None); }
 [Fact] public async Task OpenRouterValidationNeverUsesPublicCatalog() { using var client = new ProviderClient(new MockHttp((request,_) => { Assert.Equal("/api/v1/key",request.RequestUri!.AbsolutePath); return Task.FromResult(MockHttp.Json("{\"error\":\"rejected\"}",401)); })); var error = await Assert.ThrowsAsync<ProviderException>(() => client.ValidateKey(Provider.OpenRouter,"bad-key","",CancellationToken.None)); Assert.Equal("bad_key",error.Code); }
 [Fact] public async Task GeminiHasHeaderKeyAndLiteralPromptAndSkipsThoughts() { using var client = new ProviderClient(new MockHttp(async (request,token) => { Assert.Empty(request.RequestUri!.Query); Assert.Equal("gemini-key",request.Headers.GetValues("x-goog-api-key").Single()); Assert.Null(request.Headers.Authorization); using var body = JsonDocument.Parse(await request.Content!.ReadAsStringAsync(token)); Assert.Equal(0,body.RootElement.GetProperty("generationConfig").GetProperty("temperature").GetInt32()); var parts = body.RootElement.GetProperty("contents")[0].GetProperty("parts"); Assert.Contains("untrusted",parts[0].GetProperty("text").GetString()); Assert.Equal("audio/wav",parts[1].GetProperty("inline_data").GetProperty("mime_type").GetString()); return MockHttp.Json("{\"candidates\":[{\"finishReason\":\"STOP\",\"content\":{\"parts\":[{\"thought\":true,\"text\":\"secret thinking\"},{\"text\":\"Transcript: Type my email.\"}]}}]}"); })); Assert.Equal("Type my email.",await client.Transcribe(Audio,new QuillSettings { Provider = Provider.Gemini },"gemini-key",CancellationToken.None)); }
 [Theory][InlineData("{\"promptFeedback\":{\"blockReason\":\"SAFETY\"}}")][InlineData("{\"candidates\":[{\"finishReason\":\"MAX_TOKENS\",\"content\":{\"parts\":[{\"text\":\"partial\"}]}}]}")][InlineData("{\"candidates\":[{\"finishReason\":\"SAFETY\",\"content\":{\"parts\":[{\"text\":\"partial\"}]}}]}")]
 public async Task GeminiRejectsBlockedAndTruncatedOutputs(string response) { using var client = new ProviderClient(new MockHttp((_,_) => Task.FromResult(MockHttp.Json(response)))); await Assert.ThrowsAsync<ProviderException>(() => client.Transcribe(Audio,new QuillSettings { Provider = Provider.Gemini },"gemini-key",CancellationToken.None)); }
 [Theory][InlineData(401,"{}","bad_key")][InlineData(403,"{}","bad_key")][InlineData(402,"{}","quota")][InlineData(429,"{\"error\":\"quota exhausted\"}","quota")][InlineData(429,"{}","rate_limit")][InlineData(503,"{}","provider_error")][InlineData(302,"{}","redirect_blocked")]
 public async Task ErrorsMappedWithoutLeakingBody(int status,string body,string code) { using var client = new ProviderClient(new MockHttp((_,_) => Task.FromResult(MockHttp.Json(body,status)))); var error = await Assert.ThrowsAsync<ProviderException>(() => client.Transcribe(Audio,new(),"test-key",CancellationToken.None)); Assert.Equal(code,error.Code); Assert.DoesNotContain(body,error.Message); }
 [Fact] public async Task Gemini400InvalidKeyMapsToBadKey() { using var client = new ProviderClient(new MockHttp((_,_) => Task.FromResult(MockHttp.Json("{\"reason\":\"API_KEY_INVALID\"}",400)))); Assert.Equal("bad_key",(await Assert.ThrowsAsync<ProviderException>(() => client.ValidateKey(Provider.Gemini,"bad-key","",CancellationToken.None))).Code); }
 [Fact] public async Task RequestCancellationPropagates() { using var cancel = new CancellationTokenSource(); using var client = new ProviderClient(new MockHttp(async (_,token) => { cancel.Cancel(); await Task.Delay(Timeout.Infinite,token); return MockHttp.Json("{}"); })); await Assert.ThrowsAnyAsync<OperationCanceledException>(() => client.Transcribe(Audio,new(),"test-key",cancel.Token)); }
 [Theory][InlineData("",false)][InlineData("send this message",true)][InlineData("I will send this message for you",false)] public async Task CleanupGuardIsEnforced(string response,bool accepted) { using var client = new ProviderClient(new MockHttp((_,_) => Task.FromResult(MockHttp.Json(JsonSerializer.Serialize(new { choices = new[] { new { finish_reason = "stop",message = new { content = response } } } }))))); var result = await client.Cleanup("send this message",new(),"cleanup-key","notepad",CancellationToken.None); Assert.Equal(accepted ? response : "send this message",result); }
 [Fact] public async Task TruncatedCleanupFallsBackToRawEvenWhenOverlapPasses() { using var client = new ProviderClient(new MockHttp((_,_) => Task.FromResult(MockHttp.Json("{\"choices\":[{\"finish_reason\":\"length\",\"message\":{\"content\":\"Send this message\"}}]}")))); Assert.Equal("send this message",await client.Cleanup("send this message",new(),"cleanup-key","notepad",CancellationToken.None)); }
 [Fact] public async Task CleanupFailuresAndTimeoutPreserveRaw() { using var client = new ProviderClient(new MockHttp((_,_) => Task.FromResult(MockHttp.Json("{}",500)))); Assert.Equal("unchanged transcript",await client.Cleanup("unchanged transcript",new(),"cleanup-key","notepad",CancellationToken.None)); }
 [Fact] public async Task CleanupUsesIndependentProviderKeyAndStyle() { var s = new QuillSettings { Provider = Provider.Groq,CleanupAutomatic = false,CleanupProvider = Provider.Gemini,CleanupModel = "my-cleanup",DefaultStyle = WritingStyle.Formal }; using var client = new ProviderClient(new MockHttp(async (request,token) => { Assert.Equal("https://generativelanguage.googleapis.com/v1beta/openai/chat/completions",request.RequestUri!.AbsoluteUri); Assert.Equal("independent-key",request.Headers.Authorization!.Parameter); var body = await request.Content!.ReadAsStringAsync(token); Assert.Contains("my-cleanup",body); Assert.Contains("Formal style",body); return MockHttp.Json("{\"choices\":[{\"finish_reason\":\"stop\",\"message\":{\"content\":\"Hello.\"}}]}"); })); Assert.Equal("Hello.",await client.Cleanup("hello",s,"independent-key","unknown",CancellationToken.None)); }
 [Fact] public async Task CatalogFiltersUnsupportedModelsAndHandlesGeminiPagination() { int calls = 0; using var client = new ProviderClient(new MockHttp((request,_) => { calls++; if (calls == 1) return Task.FromResult(MockHttp.Json("{\"models\":[{\"name\":\"models/gemini-flash\",\"supportedGenerationMethods\":[\"generateContent\"]},{\"name\":\"models/gemini-live\",\"supportedGenerationMethods\":[\"generateContent\"]}],\"nextPageToken\":\"next token\"}")); Assert.Contains("pageToken=next%20token",request.RequestUri!.AbsoluteUri); return Task.FromResult(MockHttp.Json("{\"models\":[{\"name\":\"models/gemini-pro\",\"supportedGenerationMethods\":[\"generateContent\"]}]}")); })); Assert.Equal(new[] {"gemini-flash","gemini-pro"},(await client.Models(Provider.Gemini,"test-key","",true,CancellationToken.None)).Select(m => m.Id)); }
 [Fact] public async Task OversizedResponseIsRejected() { using var client = new ProviderClient(new MockHttp((_,_) => Task.FromResult(MockHttp.Json(new string('x',4*1024*1024+1))))); Assert.Equal("response_too_large",(await Assert.ThrowsAsync<ProviderException>(() => client.Transcribe(Audio,new(),"test-key",CancellationToken.None))).Code); }
}
